using System;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents a one-time code a partner must present to request a registration.
/// </summary>
[Table("federation_invitations")]
public class FederationInvitation
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid InvitationId { get; set; }

  /// <summary>
  /// The SHA-256 hash of the normalized code.
  /// </summary>
  public string CodeHash { get; set; } = null!;

  /// <summary>
  /// Date when the invitation was created.
  /// </summary>
  public DateTime CreatedAt { get; set; }

  /// <summary>
  /// Date when the invitation expires.
  /// </summary>
  public DateTime ExpiresAt { get; set; }

  /// <summary>
  /// Date when the invitation was used or null if it is still open.
  /// </summary>
  public DateTime? UsedAt { get; set; }

  /// <summary>
  /// The instance name of the partner which used the invitation.
  /// </summary>
  public string? UsedBy { get; set; }
}
